import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 9
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []

    try:
        for record in reader:
            if record and any(value.strip() for value in record):
                records.append(record)
    except csv.Error:
        pass

    header_index = None
    fallback_index = None

    for index, record in enumerate(records):
        if len(record) >= expected_width:
            if fallback_index is None:
                fallback_index = index
            values = record[:expected_width]
            if any(_not_numeric(value) for value in values):
                header_index = index
                break

    if header_index is None:
        header_index = fallback_index

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for record in records[header_index + 1:]:
        rows.append(record[:])

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        columns.append("extra_{}".format(len(columns) - expected_width + 1))

    normalized_rows = []
    for row in rows:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}


def _not_numeric(value):
    value = value.strip()
    if not value:
        return False
    try:
        float(value)
        return False
    except ValueError:
        return True
